import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Le coniche come intersezione fra un piano ed un cono matematico","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/d_geometria-cartesiana/dd/dda.md","filePath":"lezioni/d_geometria-cartesiana/dd/dda.md"}`),a={name:`lezioni/d_geometria-cartesiana/dd/dda.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="le-coniche-come-intersezione-fra-un-piano-ed-un-cono-matematico" tabindex="-1">Le coniche come intersezione fra un piano ed un cono matematico <a class="header-anchor" href="#le-coniche-come-intersezione-fra-un-piano-ed-un-cono-matematico" aria-label="Permalink to “Le coniche come intersezione fra un piano ed un cono matematico”">​</a></h1><blockquote><p>Definiamo un cono matematico come l&#39;insieme di tutte le rette che congiungono i punti di una circonferenza con un punto non giacente nel piano della circonferenza stessa.</p><p>Le rette si chiamano [generatrici del cono]{.text-red}, il punto si chiama [vertice]{.text-red}, la circonferenza è detta [circonferenza di base]{.text-red}, si definisce inoltre [asse del cono]{.text-red} la perpendicolare condotta dal vertice al piano della circonferenza di base.</p><hr><p>Se intersechiamo il cono con un piano non passante per il vertice otteniamo le varie coniche non degeneri.</p><p>Se prendiamo un piano passante per il vertice ed intersecante la circonferenza di base otteniamo una cosiddetta conica degenere.</p><p>Vediamo ora i vari casi possibili:</p><ul><li>Circonferenza</li><li>Ellisse</li><li>Iperbole</li><li>Parabola</li><li>Conica degenere</li></ul></blockquote>`,2)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};